function renderKingdoms(){const english=localStorage.getItem('mbokaLang')==='en',n=english?1:0;document.querySelector('#royaumes .eyebrow').textContent=english?'History and memory':'Histoire et mémoire';document.querySelector('#royaumes h2').innerHTML=english?'Kingdoms and<br>early societies.':'Royaumes et<br>sociétés anciennes.';document.querySelector('#kingdomIntro').textContent=english?'Explore four major historical formations connected to Congolese territory and Central African history.':'Explore quatre grands ensembles historiques liés au territoire congolais et à l’histoire de l’Afrique centrale.';document.querySelector('#kingdomGrid').innerHTML=kingdomProfiles.map(item=>`<article class="kingdom-card"><div class="kingdom-card-top"><div><small>${english?'HISTORICAL PROFILE':'PROFIL HISTORIQUE'}</small><h3>${item.name}</h3></div><span class="kingdom-period">${item.period[n]}</span></div><p>${item.intro[n]}</p><div class="kingdom-facts">${item.facts.map(f=>`<div class="kingdom-fact"><strong>${f[0][n]}</strong><span>${f[1][n]}</span></div>`).join('')}</div></article>`).join('')}

