function renderPresidency(){const english=localStorage.getItem('mbokaLang')==='en',n=english?1:0;document.querySelector('#presidence .eyebrow').textContent=english?'Since independence':'Depuis l’indépendance';document.querySelector('#presidence h2').innerHTML=english?'The presidency<br>through time.':'La présidence<br>à travers le temps.';document.querySelector('#presidencyIntro').textContent=english?'Meet the five presidents of the DRC since 1960 and the major transitions that shaped the country.':'Découvre les cinq présidents de la RDC depuis 1960 et les grandes transitions qui ont marqué le pays.';document.querySelector('#presidencyTimeline').innerHTML=presidencyProfiles.map((person,index)=>`<article class="presidency-card"><div class="presidency-marker"><span>${index+1}</span></div><div class="presidency-card-body"><div class="presidency-meta"><small>${person.order[n]}</small><strong>${Array.isArray(person.years)?person.years[n]:person.years}</strong></div><h3>${person.name}</h3><p>${person.text[n]}</p></div></article>`).join('');document.querySelector('#presidencyContext').innerHTML=english?'<strong>Names of the country</strong><span>Republic of the Congo (1960–1964) · Democratic Republic of the Congo (1964–1971) · Republic of Zaire (1971–1997) · Democratic Republic of the Congo (since 1997)</span>':'<strong>Les noms du pays</strong><span>République du Congo (1960–1964) · République démocratique du Congo (1964–1971) · République du Zaïre (1971–1997) · République démocratique du Congo (depuis 1997)</span>';document.querySelector('#presidencySource').innerHTML=`${english?'Reference:':'Référence :'} <a href="https://presidence.cd/anciens-presidents" target="_blank" rel="noopener noreferrer">${english?'official Presidency of the DRC records':'archives officielles de la Présidence de la RDC'}</a>.`}

