function renderNationalHeroes(){const english=localStorage.getItem('mbokaLang')==='en',n=english?1:0;document.querySelector('#heros .eyebrow').textContent=english?'Memory and courage':'Mémoire et courage';document.querySelector('#heros h2').innerHTML=english?'National heroes<br>and leading figures.':'Héros nationaux<br>et grandes figures.';document.querySelector('#heroesIntro').textContent=english?'Meet women and men whose courage, ideas or sacrifice left a mark on Congolese history.':'Découvre des femmes et des hommes dont le courage, les idées ou le sacrifice ont marqué l’histoire congolaise.';document.querySelector('#heroesNote').innerHTML=english?'<strong>An important distinction</strong><span>“National hero” is an official status. The other portraits are presented as major historical or spiritual figures.</span>':'<strong>Une distinction importante</strong><span>« Héros national » est un statut officiel. Les autres portraits sont présentés comme de grandes figures historiques ou spirituelles.</span>';document.querySelector('#heroesGrid').innerHTML=nationalHeroProfiles.map(person=>`<article class="national-hero-card"><div class="national-hero-symbol">${person.symbol}</div><div class="national-hero-meta"><small>${person.status[n]}</small><span>${english&&person.yearsEn?person.yearsEn:person.years}</span></div><h3>${person.name}</h3><p>${person.text[n]}</p></article>`).join('');document.querySelector('#heroesSource').innerHTML=english?'References: <a href="https://www.leganet.cd/Legislation/Droit%20administratif/Urbanismevoiries/Div/L.009.05.08.2002.htm" target="_blank" rel="noopener noreferrer">National Heroes Order</a> · <a href="https://presidence.cd/conseil-de-ministres/39eme_reunion_du_conseil_des_ministres" target="_blank" rel="noopener noreferrer">Kasa-Vubu</a> · <a href="https://www.vatican.va/content/john-paul-ii/it/homilies/1985/documents/hf_jp-ii_hom_19850815_beatificazione-kinshasa.html" target="_blank" rel="noopener noreferrer">Anuarite</a>.':'Références : <a href="https://www.leganet.cd/Legislation/Droit%20administratif/Urbanismevoiries/Div/L.009.05.08.2002.htm" target="_blank" rel="noopener noreferrer">Ordre des Héros nationaux</a> · <a href="https://presidence.cd/conseil-de-ministres/39eme_reunion_du_conseil_des_ministres" target="_blank" rel="noopener noreferrer">Kasa-Vubu</a> · <a href="https://www.vatican.va/content/john-paul-ii/it/homilies/1985/documents/hf_jp-ii_hom_19850815_beatificazione-kinshasa.html" target="_blank" rel="noopener noreferrer">Anuarite</a>.'}

