function renderCommunities(){const english=localStorage.getItem('mbokaLang')==='en',n=english?1:0;document.querySelector('#communautes .eyebrow').textContent=english?'Living cultures':'Cultures vivantes';document.querySelector('#communautes h2').textContent=english?'Communities and transmission':'Communautés et transmission';document.querySelector('#communityIntro').textContent=english?'Discover how knowledge, arts and values continue to move between generations.':'Découvre comment des savoirs, des arts et des valeurs continuent de circuler entre générations.';document.querySelector('#communityNote').textContent=english?'These snapshots are introductions: practices vary by family, locality and generation.':'Ces portraits sont des introductions : les pratiques varient selon les familles, les localités et les générations.';document.querySelector('#communityGrid').innerHTML=communityProfiles.map(item=>`<article class="community-card"><span>${item.icon}</span><small>${item.tag[n]}</small><h3>${item.title[n]}</h3><p>${item.text[n]}</p><strong>${item.value[n]}</strong></article>`).join('')}

