function renderFood(){const english=localStorage.getItem('mbokaLang')==='en',n=english?1:0;document.querySelector('#saveurs .eyebrow').textContent=english?'Flavours of the country':'Saveurs du pays';document.querySelector('#saveurs h2').innerHTML=english?'One cuisine,<br>a thousand variations.':'Une cuisine,<br>mille variations.';document.querySelector('#foodIntro').textContent=english?'Discover dishes, ingredients and methods connecting fields, rivers, markets and family tables.':'Découvre des plats, ingrédients et méthodes qui relient champs, rivières, marchés et tables familiales.';document.querySelector('#foodNote').textContent=english?'Recipes vary by region and family. Any cooking activity requires adult supervision; cassava must always be properly processed and cooked.':'Les recettes changent selon les régions et les familles. Toute activité de cuisine doit être réalisée avec un adulte; le manioc doit toujours être correctement préparé et cuit.';document.querySelector('#foodGrid').innerHTML=foodProfiles.map(item=>`<article class="food-card"><div class="food-visual">${item.icon}</div><div class="food-body"><small>${item.type[n]}</small><h3>${item.name}</h3><div class="food-detail"><strong>${english?'MAIN IDEA':'INGRÉDIENTS-CLÉS'}</strong><p>${item.ingredients[n]}</p></div><div class="food-detail"><strong>${english?'METHOD':'MÉTHODE'}</strong><p>${item.method[n]}</p></div></div></article>`).join('')}

const environmentProfiles=[
  {icon:'☂',tag:['CLIMAT ET SAISONS','CLIMATE & SEASONS'],title:['Des rythmes régionaux','Regional rhythms'],text:['Près de l’Équateur, les pluies sont fréquentes. Plus au nord et au sud, saisons humides et sèches alternent à des périodes différentes; l’altitude rafraîchit les hauts plateaux.','Near the Equator, rain is frequent. Farther north and south, wet and dry seasons alternate at different times; elevation cools the highlands.'],fact:['Le climat n’est pas identique partout.','Climate is not the same everywhere.']},
  {icon:'≈',tag:['EAU','WATER'],title:['Fleuve, rivières et lacs','River, tributaries & lakes'],text:['Le fleuve Congo et ses affluents drainent un immense bassin. À l’est, les lacs Albert, Édouard, Kivu et Tanganyika appartiennent au système du Rift.','The Congo River and its tributaries drain a vast basin. In the east, Lakes Albert, Edward, Kivu and Tanganyika belong to the Rift system.'],fact:['L’eau relie écosystèmes et communautés.','Water connects ecosystems and communities.']},
  {icon:'▲',tag:['GÉOLOGIE','GEOLOGY'],title:['Volcans des Virunga','Virunga volcanoes'],text:['Nyiragongo et Nyamulagira se trouvent dans le Rift est-africain. Leurs éruptions et coulées de lave transforment les paysages et peuvent menacer les populations.','Nyiragongo and Nyamulagira lie in the East African Rift. Their eruptions and lava flows reshape landscapes and can threaten communities.'],fact:['Observer les volcans aide à réduire les risques.','Monitoring volcanoes helps reduce risk.']},
  {icon:'♣',tag:['FORÊT ET CLIMAT','FOREST & CLIMATE'],title:['Bassin forestier du Congo','Congo forest basin'],text:['Les forêts stockent du carbone, influencent le cycle de l’eau et abritent une biodiversité exceptionnelle. Elles soutiennent aussi les moyens de vie de nombreuses communautés.','Forests store carbon, influence the water cycle and shelter exceptional biodiversity. They also support many community livelihoods.'],fact:['Protéger la forêt protège plusieurs systèmes à la fois.','Protecting forest safeguards many systems at once.']},
  {icon:'◈',tag:['BIODIVERSITÉ','BIODIVERSITY'],title:['Espèces remarquables','Remarkable species'],text:['L’okapi et le bonobo vivent naturellement en RDC. Le gorille de Grauer, le gorille de montagne et de nombreuses autres espèces dépendent d’habitats protégés.','Okapi and bonobo occur naturally in the DRC. Grauer’s gorilla, mountain gorilla and many other species depend on protected habitats.'],fact:['Endémique signifie lié naturellement à une aire précise.','Endemic means naturally limited to a particular area.']},
  {icon:'⌾',tag:['CONSERVATION','CONSERVATION'],title:['Cinq sites mondiaux','Five world sites'],text:['Virunga, Garamba, Kahuzi-Biega, Salonga et la Réserve de faune à okapis sont inscrits au patrimoine mondial. Conflits, braconnage et exploitation illégale menacent leur intégrité.','Virunga, Garamba, Kahuzi-Biega, Salonga and the Okapi Wildlife Reserve are World Heritage sites. Conflict, poaching and illegal exploitation threaten their integrity.'],fact:['Les communautés locales jouent un rôle essentiel.','Local communities play an essential role.']}
];
function renderEnvironment(){const english=localStorage.getItem('mbokaLang')==='en',n=english?1:0;document.querySelector('#environnement .eyebrow').textContent=english?'Nature and science':'Nature et science';document.querySelector('#environnement h2').innerHTML=english?'A country of<br>great ecosystems.':'Un pays de<br>grands écosystèmes.';document.querySelector('#environmentIntro').textContent=english?'Observe how climate, water, landforms and living things form connected systems.':'Observe comment climat, eau, relief et êtres vivants forment des systèmes liés.';document.querySelector('#environmentGrid').innerHTML=environmentProfiles.map(item=>`<article class="environment-card"><span>${item.icon}</span><small>${item.tag[n]}</small><h3>${item.title[n]}</h3><p>${item.text[n]}</p><strong>${item.fact[n]}</strong></article>`).join('');document.querySelector('#environmentAction').innerHTML=english?'<strong>Science challenge:</strong> choose an ecosystem near you and record rain, plants, animals and human activity for one week—without disturbing nature.':'<strong>Défi scientifique :</strong> choisis un écosystème près de chez toi et note pendant une semaine la pluie, les plantes, les animaux et les activités humaines observés—sans déranger la nature.'}

