function renderResources(){const english=localStorage.getItem('mbokaLang')==='en',n=english?1:0;document.querySelector('#ressources .eyebrow').textContent=english?'Minerals and responsibility':'Minéraux et responsabilité';document.querySelector('#ressources h2').innerHTML=english?'From rock<br>to our objects.':'De la roche<br>à nos objets.';document.querySelector('#resourceIntro').textContent=english?'Learn where selected resources occur, how they are used and why their management affects people and nature.':'Comprends où se trouvent quelques ressources, à quoi elles servent et pourquoi leur gestion concerne les personnes comme la nature.';document.querySelector('#resourceGrid').innerHTML=resourceProfiles.map(item=>`<article class="resource-card"><span class="resource-symbol">${item.symbol}</span><h3>${item.name[n]}</h3><div class="resource-detail"><strong>${english?'WHERE?':'OÙ ?'}</strong><p>${item.where[n]}</p></div><div class="resource-detail"><strong>${english?'EVERYDAY USES':'USAGES'}</strong><p>${item.uses[n]}</p></div></article>`).join('');document.querySelector('#supplyChain').innerHTML=supplySteps.map(step=>`<div class="supply-step"><span>${step.n}</span><strong>${step.title[n]}</strong><p>${step.text[n]}</p></div>`).join('');document.querySelector('#resourcePrinciple').innerHTML=english?'<strong>Responsible management</strong> means protecting workers and children, consulting communities, tracing supply chains, reducing pollution, sharing benefits fairly and repairing damaged land.':'<strong>Une gestion responsable</strong> signifie protéger travailleurs et enfants, consulter les communautés, tracer les chaînes d’approvisionnement, réduire la pollution, partager équitablement les bénéfices et restaurer les terres.'}

