function renderCreativity(){const english=localStorage.getItem('mbokaLang')==='en',n=english?1:0;document.querySelector('#creativite .eyebrow').textContent=english?'Living arts':'Arts vivants';document.querySelector('#creativite h2').innerHTML=english?'Create, tell stories,<br>make people dance.':'Créer, raconter,<br>faire danser.';document.querySelector('#creativityIntro').textContent=english?'Explore historical and contemporary practices that transform sound, movement, materials and stories.':'Explore des pratiques anciennes et contemporaines qui transforment sons, mouvements, matières et récits.';document.querySelector('#creativityGrid').innerHTML=creativityProfiles.map(item=>`<article class="creativity-card"><span>${item.icon}</span><small>${item.tag[n]}</small><h3>${item.title[n]}</h3><p>${item.text[n]}</p><strong>${item.idea[n]}</strong></article>`).join('');document.querySelector('#creativeChallenge').innerHTML=english?'<strong>Creative challenge</strong>Create a four-panel story about your neighbourhood using only shapes, three colours and one sentence in a Congolese language you know or are learning.':'<strong>Défi créatif</strong>Crée une histoire en quatre cases sur ton quartier avec seulement des formes, trois couleurs et une phrase dans une langue congolaise que tu connais ou apprends.'}

