function updateGuidedPath(){const learned=explored.length>0,played=localStorage.getItem('mbokaGuidedQuizCompleted')==='1',steps=[learned,played,false],next=steps.findIndex(done=>!done);document.querySelectorAll('[data-guided-step]').forEach((step,index)=>{step.classList.toggle('completed',steps[index]);step.classList.toggle('active',index===next);if(index===next)step.setAttribute('aria-current','step');else step.removeAttribute('aria-current')})}
