let lingalaDeck=[],lingalaIndex=0,lingalaPoints=0,lingalaAnswered=false;
const lingalaShuffle=items=>[...items].sort(()=>Math.random()-.5);
function showLingalaRound(){const english=localStorage.getItem('mbokaLang')==='en',item=lingalaDeck[lingalaIndex],key=english?'en':'fr',answers=lingalaShuffle([item[key],...lingalaShuffle(lingalaWords.filter(x=>x!==item)).slice(0,3).map(x=>x[key])]);lingalaAnswered=false;document.querySelector('#lingalaRound').textContent=`${lingalaIndex+1} / 5`;document.querySelector('#lingalaScore').textContent=lingalaPoints;document.querySelector('#lingalaWord').textContent=item.word;document.querySelector('#lingalaOptions').innerHTML=answers.map(answer=>`<button class="lingala-option" data-answer="${answer}">${answer}</button>`).join('');document.querySelector('#lingalaFeedback').textContent='';document.querySelector('#lingalaNext').hidden=true}
function startLingala(){const english=localStorage.getItem('mbokaLang')==='en';lingalaDeck=lingalaShuffle(lingalaWords).slice(0,5);lingalaIndex=0;lingalaPoints=0;document.querySelector('#lingalaGame .eyebrow').textContent=english?'Language challenge':'Défi linguistique';document.querySelector('#lingalaGame h2').innerHTML=english?'Mbote!<br>Practise Lingala':'Mbote !<br>Pratique le lingala';document.querySelector('#lingalaGame .lingala-intro>p').textContent=english?'Choose the correct meaning. Five quick rounds to remember your first words.':'Choisis la bonne signification. Cinq manches rapides pour retenir les premiers mots.';document.querySelector('#lingalaPrompt').textContent=english?'WHAT DOES THIS MEAN?':'QUE SIGNIFIE…';document.querySelector('#lingalaRestart').textContent=english?'Play again':'Rejouer';document.querySelector('#lingalaResult').hidden=true;document.querySelector('#lingalaWord').parentElement.hidden=false;document.querySelector('#lingalaOptions').hidden=false;document.querySelector('#lingalaPrompt').hidden=false;showLingalaRound()}
document.querySelector('#lingalaOptions').addEventListener('click',e=>{const button=e.target.closest('.lingala-option');if(!button||lingalaAnswered)return;lingalaAnswered=true;const english=localStorage.getItem('mbokaLang')==='en',correct=lingalaDeck[lingalaIndex][english?'en':'fr'],ok=button.dataset.answer===correct;if(ok)lingalaPoints+=100;document.querySelectorAll('.lingala-option').forEach(option=>{option.disabled=true;option.classList.toggle('correct',option.dataset.answer===correct)});if(!ok)button.classList.add('wrong');document.querySelector('#lingalaScore').textContent=lingalaPoints;document.querySelector('#lingalaFeedback').textContent=ok?(english?'Correct—malamu!':'Correct — malamu !'):(english?`The answer is: ${correct}.`:`La réponse est : ${correct}.`);document.querySelector('#lingalaNext').textContent=lingalaIndex===4?(english?'See result →':'Voir le résultat →'):(english?'Continue →':'Continuer →');document.querySelector('#lingalaNext').hidden=false});
document.querySelector('#lingalaNext').addEventListener('click',()=>{if(++lingalaIndex<5)return showLingalaRound();const english=localStorage.getItem('mbokaLang')==='en';document.querySelector('#lingalaWord').parentElement.hidden=true;document.querySelector('#lingalaOptions').hidden=true;document.querySelector('#lingalaPrompt').hidden=true;document.querySelector('#lingalaNext').hidden=true;document.querySelector('#lingalaFeedback').textContent='';document.querySelector('#lingalaResult').hidden=false;document.querySelector('#lingalaResultTitle').textContent=lingalaPoints>=400?'Malamu!':(english?'Keep practising!':'Continue à pratiquer !');document.querySelector('#lingalaResultText').textContent=english?`You scored ${lingalaPoints} out of 500 points.`:`Tu as obtenu ${lingalaPoints} points sur 500.`});
