// Province Sprint: a replayable capital-matching challenge.
let sprintDeck=[], sprintIndex=0, sprintScore=0, sprintStreak=0, sprintLives=3, sprintAnswered=false,sprintMode='solo',sprintTeamScores=[0,0];
const sprintBest=document.querySelector('#sprintBest'), sprintProvince=document.querySelector('#sprintProvince'), sprintOptions=document.querySelector('#sprintOptions'), sprintFeedback=document.querySelector('#sprintFeedback'), sprintNext=document.querySelector('#sprintNext');
function shuffled(items){return [...items].sort(()=>Math.random()-.5)}
function startSprint(){
  const english=localStorage.getItem('mbokaLang')==='en';document.querySelector('[data-sprint-mode="solo"] strong').textContent='Solo';document.querySelector('[data-sprint-mode="solo"] small').textContent=english?'3 LIVES':'3 VIES';document.querySelector('[data-sprint-mode="team"] strong').textContent=english?'Two teams':'Deux équipes';document.querySelector('[data-sprint-mode="team"] small').textContent=english?'10 TURNS':'10 TOURS';sprintDeck=shuffled(provinces).slice(0,10); sprintIndex=0; sprintScore=0; sprintStreak=0; sprintLives=3;sprintTeamScores=[0,0];
  document.querySelector('#sprintPlay').hidden=false; document.querySelector('#sprintResult').hidden=true; showSprintRound();
}
function showSprintRound(){
  sprintAnswered=false; const correct=sprintDeck[sprintIndex]; const distractors=shuffled(provinces.filter(p=>p[1]!==correct[1])).slice(0,3).map(p=>p[1]); const choices=shuffled([correct[1],...distractors]);
  sprintProvince.textContent=correct[0]; document.querySelector('#sprintRound').textContent=`${sprintIndex+1} / 10`; sprintOptions.innerHTML=choices.map(city=>`<button class="sprint-option" data-city="${city}">${city}</button>`).join(''); sprintFeedback.textContent=''; sprintFeedback.className='sprint-feedback'; sprintNext.classList.remove('show'); updateSprintStatus();
}
function updateSprintStatus(){
  if(sprintMode==='team'){const english=localStorage.getItem('mbokaLang')==='en',team=sprintIndex%2;document.querySelector('#sprintStreak').parentElement.querySelector('small').textContent=english?'TURN':'TOUR';document.querySelector('#sprintStreak').textContent=`${english?'Team':'Équipe'} ${team?'B':'A'}`;document.querySelector('#sprintLives').parentElement.querySelector('small').textContent=english?'TEAM A':'ÉQUIPE A';document.querySelector('#sprintLives').textContent=sprintTeamScores[0];document.querySelector('#sprintScore').parentElement.querySelector('small').textContent=english?'TEAM B':'ÉQUIPE B';document.querySelector('#sprintScore').textContent=sprintTeamScores[1];return}document.querySelector('#sprintStreak').parentElement.querySelector('small').textContent=localStorage.getItem('mbokaLang')==='en'?'STREAK':'SÉRIE';document.querySelector('#sprintLives').parentElement.querySelector('small').textContent=localStorage.getItem('mbokaLang')==='en'?'LIVES':'VIES';document.querySelector('#sprintScore').parentElement.querySelector('small').textContent='SCORE';document.querySelector('#sprintStreak').textContent=`${sprintStreak} 🔥`; document.querySelector('#sprintLives').textContent=`${'♥ '.repeat(sprintLives)}${'♡ '.repeat(3-sprintLives)}`.trim(); document.querySelector('#sprintScore').textContent=sprintScore;
}
function answerSprint(city){
  if(sprintAnswered)return; sprintAnswered=true; const correct=sprintDeck[sprintIndex][1]; const buttons=[...sprintOptions.children]; buttons.forEach(b=>{b.disabled=true;if(b.dataset.city===correct)b.classList.add('correct')});
  const english=localStorage.getItem('mbokaLang')==='en';if(sprintMode==='team'){const team=sprintIndex%2;if(city===correct){sprintTeamScores[team]+=100;sprintFeedback.textContent=`${english?'Team':'Équipe'} ${team?'B':'A'}: ${english?'correct':'exact'} ! +100`;sprintFeedback.classList.add('good')}else{buttons.find(b=>b.dataset.city===city).classList.add('wrong');sprintFeedback.textContent=english?`The correct answer was ${correct}.`:`La bonne réponse était ${correct}.`;sprintFeedback.classList.add('bad')}}else if(city===correct){sprintStreak++;const gain=100+(sprintStreak-1)*20;sprintScore+=gain;sprintFeedback.textContent=`Exact ! ${correct} est bien le chef-lieu. +${gain} points`;sprintFeedback.classList.add('good')}else{sprintLives--;sprintStreak=0;buttons.find(b=>b.dataset.city===city).classList.add('wrong');sprintFeedback.textContent=`La bonne réponse était ${correct}.`;sprintFeedback.classList.add('bad')}
  updateSprintStatus(); sprintNext.textContent=(sprintIndex===9||(sprintMode==='solo'&&sprintLives===0))?(english?'See result →':'Voir le résultat →'):(english?'Next round →':'Manche suivante →'); sprintNext.classList.add('show');
}
function finishSprint(){
  const english=localStorage.getItem('mbokaLang')==='en';document.querySelector('#sprintPlay').hidden=true;document.querySelector('#sprintResult').hidden=false;if(sprintMode==='team'){const [a,b]=sprintTeamScores,winner=a===b?(english?'Tie game!':'Égalité !'):(english?`Team ${a>b?'A':'B'} wins!`:`L’équipe ${a>b?'A':'B'} gagne !`);document.querySelector('#sprintFinalScore').textContent=`A · ${a} — B · ${b}`;document.querySelector('#sprintResultTitle').textContent=winner;document.querySelector('#sprintResultText').textContent=english?'Ten alternating turns completed. Replay for a new province draw.':'Dix tours alternés terminés. Rejouez pour un nouveau tirage de provinces.';document.querySelector('#sprintRestart').textContent=english?'New sprint':'Nouveau sprint';return}document.querySelector('#sprintFinalScore').textContent=`${sprintScore} points`;document.querySelector('#sprintResultTitle').textContent=sprintScore>=1200?'Maître des provinces !':sprintScore>=700?'Très beau parcours !':'Continue ton exploration !';document.querySelector('#sprintResultText').textContent=`Tu as terminé ${sprintIndex+1} manche${sprintIndex?'s':''}. Rejoue : les provinces et les réponses changent à chaque sprint.`;
  const best=Math.max(sprintScore,Number(localStorage.getItem('mbokaSprintBest')||0));localStorage.setItem('mbokaSprintBest',best);sprintBest.textContent=best;
}
sprintOptions.addEventListener('click',e=>{const button=e.target.closest('[data-city]');if(button)answerSprint(button.dataset.city)});
sprintNext.addEventListener('click',()=>{if(sprintIndex===9||(sprintMode==='solo'&&sprintLives===0))finishSprint();else{sprintIndex++;showSprintRound()}});
document.querySelector('#sprintMode').addEventListener('click',e=>{const button=e.target.closest('[data-sprint-mode]');if(!button||button.dataset.sprintMode===sprintMode)return;sprintMode=button.dataset.sprintMode;document.querySelectorAll('[data-sprint-mode]').forEach(item=>item.classList.toggle('active',item===button));startSprint()});
document.querySelector('#sprintRestart').addEventListener('click',startSprint);
sprintBest.textContent=localStorage.getItem('mbokaSprintBest')||0;
startSprint();

