let soundEnabled=localStorage.getItem('mbokaSound')!=='off';
const speechRates=[.75,.88,1,1.15];
function speechRate(){const saved=Number(localStorage.getItem('mbokaSpeechRate'));return speechRates.includes(saved)?saved:.88}
function updateSpeechControls(){const english=localStorage.getItem('mbokaLang')==='en',lessonControl=document.querySelector('#lessonSpeak'),rateControl=document.querySelector('#speechRate');if(lessonControl){const label=english?'Listen to the lesson':'Écouter la leçon';lessonControl.setAttribute('aria-label',label);lessonControl.title=label}if(rateControl){rateControl.value=String(speechRate());const label=english?'Reading speed':'Vitesse de lecture';rateControl.setAttribute('aria-label',label);rateControl.title=label;document.querySelector('#speechRateLabel').setAttribute('aria-label',label)}}
