function showAudioNotice(message){const old=document.querySelector('.audio-notice');if(old)old.remove();const notice=document.createElement('div');notice.className='audio-notice';notice.textContent=message;document.body.appendChild(notice)}
function speakPhrase(text,control){
  if(!soundEnabled)return showAudioNotice(localStorage.getItem('mbokaLang')==='en'?'Audio is turned off.':'Le son est désactivé.');if(!('speechSynthesis'in window))return showAudioNotice(localStorage.getItem('mbokaLang')==='en'?'Speech is not supported by this browser.':'La lecture audio n’est pas disponible dans ce navigateur.');
  speechSynthesis.cancel();document.querySelectorAll('.speaking').forEach(el=>el.classList.remove('speaking'));const utterance=new SpeechSynthesisUtterance(text);utterance.lang=localStorage.getItem('mbokaLang')==='en'?'en-US':'fr-FR';utterance.rate=speechRate();const voice=speechSynthesis.getVoices().find(v=>v.lang.toLowerCase().startsWith(utterance.lang.slice(0,2).toLowerCase()));if(voice)utterance.voice=voice;if(control)control.classList.add('speaking');utterance.onend=utterance.onerror=()=>control?.classList.remove('speaking');speechSynthesis.speak(utterance);
}
document.querySelector('#soundToggle').addEventListener('click',()=>{soundEnabled=!soundEnabled;localStorage.setItem('mbokaSound',soundEnabled?'on':'off');if(!soundEnabled&&'speechSynthesis'in window)speechSynthesis.cancel();updateSoundButton()});
document.querySelector('#speechRate').addEventListener('change',event=>{const rate=Number(event.target.value);localStorage.setItem('mbokaSpeechRate',String(speechRates.includes(rate)?rate:.88));updateSpeechControls()});
document.querySelector('#mapSpeak').addEventListener('click',e=>{const english=localStorage.getItem('mbokaLang')==='en';if(mapMode==='territories'&&selectedMapTerritory>=0){const territory=drcTerritories[selectedMapTerritory];speakPhrase(english?`${territory.name}, territory of ${territory.province} province.`:`${territory.name}, territoire de la province ${territory.province}.`,e.currentTarget);return}if(selectedMapProvince<0)return;const p=provinces[selectedMapProvince],d=english&&window.enContent?window.enContent.provinces[selectedMapProvince]:provinceDetails[selectedMapProvince];speakPhrase(`${p[0]}. ${english?'Capital':'Chef-lieu'}: ${p[1]}. ${d[2]}`,e.currentTarget)});
document.querySelector('#lessonSpeak').addEventListener('click',e=>{
  const facts=[...document.querySelectorAll('#lessonFacts .lesson-fact')].map(item=>`${item.querySelector('strong')?.textContent}. ${item.querySelector('p')?.textContent}`).join(' ');
  speakPhrase(`${document.querySelector('#lessonTitle').textContent}. ${document.querySelector('#lessonLead').textContent} ${facts}`,e.currentTarget);
});
updateSoundButton();
updateSpeechControls();
showQuestion();
startMemory();
renderDaily();
